CREATE TABLE `bookings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `booking_number` varchar(255) NOT NULL,
  `customer_id` int(11) NOT NULL,
  `community_id` int(11) DEFAULT NULL,
  `provider_id` int(11) DEFAULT NULL,
  `provider_profile_id` int(11) DEFAULT NULL,
  `service_id` int(11) NOT NULL,
  `service_title` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `date` varchar(255) NOT NULL,
  `time` varchar(255) NOT NULL,
  `address` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`address`)),
  `status` enum('pending','requested','confirmed','provider_assigned','accepted','rejected','on_the_way','arrived','in_progress','completed','cancelled') DEFAULT 'requested',
  `payment_method` enum('card','cash','wallet','upi') DEFAULT 'cash',
  `payment_status` enum('pending','processing','paid','failed','refunded','cash_pending','cash_received') DEFAULT 'pending',
  `amount` float NOT NULL,
  `customer_notes` text DEFAULT NULL,
  `status_timeline` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`status_timeline`)),
  `provider_location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`provider_location`)),
  `cancellation_reason` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `service_location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`service_location`)),
  `pricing` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pricing`)),
  `problem_description` text DEFAULT NULL,
  `media_attachments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`media_attachments`)),
  `additional_charges` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`additional_charges`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `booking_number` (`booking_number`),
  UNIQUE KEY `idx_booking_number` (`booking_number`),
  UNIQUE KEY `booking_number_2` (`booking_number`),
  UNIQUE KEY `booking_number_3` (`booking_number`),
  UNIQUE KEY `bookings_booking_number` (`booking_number`),
  KEY `provider_profile_id` (`provider_profile_id`),
  KEY `bookings_customer_id` (`customer_id`),
  KEY `bookings_provider_id` (`provider_id`),
  KEY `bookings_service_id` (`service_id`),
  KEY `bookings_status` (`status`),
  KEY `bookings_date_time` (`date`,`time`),
  KEY `bookings_community_id` (`community_id`),
  CONSTRAINT `bookings_ibfk_10` FOREIGN KEY (`provider_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bookings_ibfk_11` FOREIGN KEY (`provider_profile_id`) REFERENCES `provider_profiles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bookings_ibfk_12` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `bookings_ibfk_9` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `fk_bookings_community` FOREIGN KEY (`community_id`) REFERENCES `communities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
