DROP TABLE IF EXISTS `provider_daily_availabilities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provider_daily_availabilities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `provider_id` int(11) NOT NULL COMMENT 'User ID of the provider',
  `provider_profile_id` int(11) DEFAULT NULL,
  `date` varchar(10) NOT NULL COMMENT 'Format YYYY-MM-DD',
  `is_available` tinyint(1) DEFAULT 1,
  `is_day_off` tinyint(1) DEFAULT 0,
  `start_time` varchar(20) DEFAULT '09:00 AM',
  `end_time` varchar(20) DEFAULT '06:00 PM',
  `busy_intervals` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`busy_intervals`)),
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider_daily_availabilities_provider_id_date` (`provider_id`,`date`),
  KEY `provider_daily_availabilities_date` (`date`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
