--
-- Table structure for table `provider_profiles`
--

DROP TABLE IF EXISTS `provider_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provider_profiles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `business_name` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `experience_years` int(11) DEFAULT 2,
  `rating` float DEFAULT 0,
  `review_count` int(11) DEFAULT 0,
  `hourly_rate` float DEFAULT 299,
  `bio` text DEFAULT NULL,
  `is_approved` tinyint(1) DEFAULT 0,
  `is_available` tinyint(1) DEFAULT 0,
  `verification_status` enum('verified','pending','rejected') DEFAULT 'pending',
  `location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`location`)),
  `current_location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`current_location`)),
  `id_proof_url` varchar(255) DEFAULT '',
  `skills` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`skills`)),
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `service_radius` int(11) DEFAULT 15,
  `working_days` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`working_days`)),
  `working_hours` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`working_hours`)),
  `breaks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`breaks`)),
  `blocked_dates` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`blocked_dates`)),
  `service_duration` int(11) DEFAULT 60,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `address` varchar(255) DEFAULT '',
  `city` varchar(255) DEFAULT 'Chennai',
  `state` varchar(255) DEFAULT 'Tamil Nadu',
  `pincode` varchar(255) DEFAULT '',
  `service_radius_km` int(11) DEFAULT 15,
  `availability_status` enum('AVAILABLE','BUSY','OFFLINE') DEFAULT 'OFFLINE',
  `is_active` tinyint(1) DEFAULT 0,
  `completed_jobs` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  UNIQUE KEY `provider_profiles_user_id` (`user_id`),
  KEY `provider_profiles_category` (`category`),
  KEY `provider_profiles_is_approved` (`is_approved`),
  KEY `provider_profiles_is_active` (`is_active`),
  KEY `provider_profiles_availability_status` (`availability_status`),
  KEY `provider_profiles_verification_status` (`verification_status`),
  KEY `provider_profiles_latitude_longitude` (`latitude`,`longitude`),
  CONSTRAINT `provider_profiles_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
