--
-- Table structure for table `provider_services`
--

DROP TABLE IF EXISTS `provider_services`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provider_services` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `provider_profile_id` int(11) NOT NULL,
  `service_id` int(11) NOT NULL,
  `custom_price` float DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `base_price` float DEFAULT NULL,
  `pricing_type` enum('fixed','starting_from','inspection_required') DEFAULT 'fixed',
  `is_active` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider_services_service_id_provider_profile_id_unique` (`provider_profile_id`,`service_id`),
  KEY `provider_services_provider_profile_id_service_id` (`provider_profile_id`,`service_id`),
